## Cedar schema
```cedarschema
namespace AOB {
  type approve_workorderInput = {
    site_id: String,
    wonum: String
  };

  type asset_detailInput = {
    asset_id: String,
    site_name: String
  };

  type asset_idsInput = {
    site_name: String
  };

  type assetsInput = {
    assettype?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    site_name: String
  };

  type assign_technicianInput = {
    craft?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    hours_planned?: AOB::Number,
    labor_code: String,
    site_id: String,
    start_date?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    wonum: String
  };

  type cancel_workorderInput = {
    reason?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    site_id: String,
    wonum: String
  };

  type close_workorderInput = {
    actual_hours?: AOB::Number,
    failure_code?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    resolution_notes?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    site_id: String,
    wonum: String
  };

  type find_assets_by_sensorsInput = {
    match?: String,
    sensors: Set<String>,
    site_name: String,
    source?: String,
    substring?: Bool
  };

  type generate_work_orderInput = {
    aob_source?: {
      typeChoice0?: AOB::generate_work_order::Input::aob_source::TypeChoice0,
      typeChoice1?: AOB::Null
    },
    asset_num: String,
    description: String,
    location?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    notes?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    priority?: Long,
    reported_by?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    site_id: String,
    wonum?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    work_type?: String
  };

  type get_failure_codesInput = {
    code?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    }
  };

  type get_my_assigned_workordersInput = {
    labor_code: String,
    open_only?: Bool,
    site_id?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    }
  };

  type get_schedule_calendarInput = {
    date_from?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    date_to?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
