  type get_workorderInput = {
    site_id: String,
    wonum: String
  };

  type get_workorder_actuals_vs_plannedInput = {
    site_id: String,
    wonum: String
  };

  type get_workorder_costsInput = {
    site_id: String,
    wonum: String
  };

  type get_workorder_kpisInput = {
    period_months?: Long,
    site_id: String
  };

  type get_workorder_tasksInput = {
    site_id: String,
    wonum: String
  };

  type historyInput = {
    asset_id: String,
    cursor?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    end?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    limit?: Long,
    sensors?: {
      typeChoice0?: Set<String>,
      typeChoice1?: AOB::Null
    },
    site_name: String,
    start?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
