    date_from?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    date_to?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    page_num?: Long,
    page_size?: Long,
    priority?: {
      typeChoice0?: Long,
      typeChoice1?: AOB::Null
    },
    site_id?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    status?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    }
  };

  type measured_sensorsInput = {
    asset_id: String,
    site_name: String
  };

  type sensor_coverageInput = {
    asset_id: String,
    site_name: String
  };

  type sensor_statsInput = {
    asset_id: String,
    end?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    sensor?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    site_name: String,
    start?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    }
  };

  type sitesInput = {  };

  type stream_extentInput = {
    asset_id: String,
    end?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    sensor?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    site_name: String,
    start?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    }
  };

  type update_workorderInput = {
    asset_num?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    description?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    failure_code?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    location?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    notes?: {
      typeChoice0?: String,
      typeChoice1?: AOB::Null
    },
    priority?: {
      typeChoice0?: Long,
      typeChoice1?: AOB::Null
    },
    site_id: String,
    wonum: String
  };

  entity McpServer;

  entity Null;

  entity Number;

  entity User;

  action "approve_workorder" appliesTo {
    principal: [User],
    resource: [McpServer],
    context: {
      input: approve_workorderInput
    }
  };

  action "asset_detail" appliesTo {
    principal: [User],
    resource: [McpServer],
    context: {
      input: asset_detailInput
    }
  };

  action "asset_ids" appliesTo {
    principal: [User],
    resource: [McpServer],
    context: {
      input: asset_idsInput
    }
  };

  action "assets" appliesTo {
    principal: [User],
    resource: [McpServer],
    context: {
      input: assetsInput
    }
  };

  action "assign_technician" appliesTo {
    principal: [User],
    resource: [McpServer],
    context: {
      input: assign_technicianInput
    }
  };

  action "cancel_workorder" appliesTo {
    principal: [User],
    resource: [McpServer],
    context: {
      input: cancel_workorderInput
    }
  };

  action "close_workorder" appliesTo {
    principal: [User],
    resource: [McpServer],
    context: {
      approval?: PGI::Approval,
      input: close_workorderInput
    }
  };

  action "find_assets_by_sensors" appliesTo {
    principal: [User],
    resource: [McpServer],
    context: {
      input: find_assets_by_sensorsInput
    }
  };

  action "generate_work_order" appliesTo {
    principal: [User],
    resource: [McpServer],
    context: {
      input: generate_work_orderInput
    }
  };

  action "get_failure_codes" appliesTo {
    principal: [User],
    resource: [McpServer],
    context: {
      input: get_failure_codesInput
    }
  };

  action "get_my_assigned_workorders" appliesTo {
    principal: [User],
    resource: [McpServer],
    context: {
      input: get_my_assigned_workordersInput
    }
  };

  action "get_schedule_calendar" appliesTo {
    principal: [User],
    resource: [McpServer],
    context: {
      input: get_schedule_calendarInput
    }
  };

  action "get_workorder" appliesTo {
    principal: [User],
    resource: [McpServer],
    context: {
      input: get_workorderInput
    }
  };

  action "get_workorder_actuals_vs_planned" appliesTo {
    principal: [User],
    resource: [McpServer],
    context: {
      input: get_workorder_actuals_vs_plannedInput
    }
  };

  action "get_workorder_costs" appliesTo {
    principal: [User],
    resource: [McpServer],
    context: {
      input: get_workorder_costsInput
    }
  };

  action "get_workorder_kpis" appliesTo {
    principal: [User],
    resource: [McpServer],
    context: {
      input: get_workorder_kpisInput
    }
  };

  action "get_workorder_tasks" appliesTo {
    principal: [User],
    resource: [McpServer],
    context: {
      input: get_workorder_tasksInput
    }
  };

  action "history" appliesTo {
    principal: [User],
    resource: [McpServer],
    context: {
      input: historyInput
    }
  };

  action "installed_sensors" appliesTo {
    principal: [User],
